node --input-type=module -e '
import { isAuthorized } from "./src/auth.mjs";
const cases = [
  ["Bearer abc", "abc", true],
  ["xBearer abc", "abc", false],
  ["Bearer abcx", "abc", false],
  ["Bearer  abc", "abc", false],
  ["Bearer abc ", "abc", false],
  ["bearer abc", "abc", false],
  ["abc", "abc", false],
  [undefined, "abc", false],
  [null, "abc", false],
  [123, "abc", false],
  [{}, "abc", false],
];
let ok = true;
for (const [h, t, expected] of cases) {
  const got = isAuthorized(h, t);
  if (got !== expected) { ok = false; console.log("FAIL", h, "=>", got, "expected", expected); }
}
console.log(ok ? "edge cases passed" : "edge cases failed");
'

